    if (i == n) return 0;
    return a[i] + rsum(a, i+1, n);
}
// 2) pairwise tree (fibonacci)
long long fib(int n){
    if (n <= 1) return n;
    return fib(n-1) + fib(n-2);      // TWO branches!
}
// 3) palindrome shrink
bool pal(string& s, int l, int r){
    if (l >= r) return true;
    return s[l]==s[r] && pal(s, l+1, r-1);
}
// 4) fast-ish power (halving!)
ll pw(ll b, ll e){
    if (e == 0) return 1;
    ll half = pw(b, e/2);
    return e % 2 ? half * b * half : half * half;
