# archetype 1: linear fold
def rsum(a, i=0):
    return 0 if i == len(a) else a[i] + rsum(a, i+1)

# archetype 2: branching tree (fibonacci)
def fib(n):
    return n if n <= 1 else fib(n-1) + fib(n-2)

# archetype 3: palindrome shrink
def pal(s, l, r):
    return True if l >= r else s[l]==s[r] and pal(s, l+1, r-1)

# archetype 4: halving power
def pw(b, e):
    if e == 0: return 1
    half = pw(b, e//2)
    return half*b*half if e % 2 else half*half
